int32_t emoji_font_lookup(uint32_t code) {
    int32_t lo = 0, hi = EMOJI_FONT_COUNT - 1;
    while (lo <= hi) {
        int32_t mid = (lo + hi) / 2;
        if (emoji_code_table[mid] == code) return mid;
        if (emoji_code_table[mid] < code) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

void emoji_font_draw_char(uint32_t x, uint32_t y, uint32_t code, uint32_t color) {
    int32_t idx = emoji_font_lookup(code);
    if (idx < 0) return;
    const uint8_t* glyph = emoji_font[idx];
    for (uint32_t row = 0; row < EMOJI_FONT_H; row++) {
        uint8_t hi = glyph[row * 2];
        uint8_t lo = glyph[row * 2 + 1];
        for (uint32_t col = 0; col < 8; col++) {
            if (hi & (1 << (7 - col)))
                fb_set_pixel(x + col, y + row, color);
        }
        for (uint32_t col = 0; col < 8; col++) {
            if (lo & (1 << (7 - col)))
                fb_set_pixel(x + 8 + col, y + row, color);
        }
    }
}
